def encode(s):
    """Run-length encode *s*.

    Each run of identical characters becomes the character followed by the
    run length.  A length of 1 is omitted.
    """
    if not s:
        return ""

    result = []
    current = s[0]
    count = 1

    for ch in s[1:]:
        if ch == current:
            count += 1
        else:
            result.append(current)
            if count > 1:
                result.append(str(count))
            current = ch
            count = 1

    result.append(current)
    if count > 1:
        result.append(str(count))

    return "".join(result)


def decode(s):
    """Decode a run-length encoded string produced by :func:`encode`."""
    result = []
    i = 0
    n = len(s)

    while i < n:
        ch = s[i]
        i += 1

        start = i
        while i < n and s[i].isdigit():
            i += 1

        count = int(s[start:i]) if i > start else 1
        result.append(ch * count)

    return "".join(result)
